/* From Uiverse.io by ahmedgamal-hub - Tags: card, about me, blur filter, animated, circle loader, border, advanced, box-shadow */
@-webkit-keyframes spinner-border {
  to {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}

@keyframes spinner-border {
  to {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}

.__UIV_SCOPE__ .one-div {
  position: relative;
  font-size: 20px;
  color: #fff;
  text-align: center;
  display: inline-block;
  width: 15rem;
  height: 15rem;
  vertical-align: text-center;
}

.__UIV_SCOPE__ .one-div::after {
  content: '';
  position: absolute;
  left: 0;
  top: -10px;
  width: 100%;
  height: 100%;
  border: 0.25em solid currentColor;
  border-right-color: #2AE4FF;
  border-top-color: #2AE4FF;
  border-bottom-color: #2AE4FF;
  border-radius: 50%;
  box-shadow: 0 0 3px #fff, 0 0 10px #fff, 0 0 20px #fff, 0 0 40px #0ba9ca,
  0 0 110px #ED306F, 0 0 80px #0ba9ca;
  -webkit-animation: spinner-border 7s linear infinite;
  animation: spinner-border 7s linear infinite;
}
